import optimizelySDK, { UserAttributes } from '@optimizely/optimizely-sdk';
import { Store } from 'effector';
import FeatureToggles from './model/FeatureToggles';
interface FeatureToggleService {
    loadToggles(): void;
    isFeatureEnabled(featureToggleName: string, zone?: string): boolean;
    isFeatureEnabledAudiences(featureToggleName: string, userId: string, attributes: UserAttributes): boolean;
    mockFeatureToggle(featureToggleName: string, mockedStatus: boolean | string): void;
    getStore(): Store<FeatureToggles>;
    getInstance(): optimizelySDK.Client;
}
export default FeatureToggleService;
